insert into public.makers (id, slug, name, studio, city, country, categories, quote, bio, portrait_url, cover_url, style, sections, status, extras, sort) values ('inez', 'inez', 'Inez', 'Studio Serein', 'Vilnius', 'LT', array['jewelry']::text[], 'I want a ring to feel like a tiny sculpture you can keep close.', 'I make silver rings one at a time in a small studio in Vilnius. I carve each shape in wax first, so every ring keeps a little of my hand in it. I like pieces that look a bit imperfect up close.', '/img/inez.jpg', '/img/rings-set.jpg', 'light', array['featured', 'pieces', 'journal', 'about']::text[], 'approved', '{"craft":"Silver rings","material":"Recycled silver","replyTime":"about a day","acceptsCustom":true,"work":["/img/rings-set.jpg","/img/flow-ring.jpg","/img/soft-loop.jpg"],"meet":{"image":"/img/inez.jpg","qa":[["What do you make?","Silver rings, mostly one at a time, in a small studio in Vilnius."],["Why by hand?","I like pieces that feel a little imperfect. You can still see where my hands shaped them."],["Do you take commissions?","Yes, in your size or as a gift. Ask me anything."]]},"process":{"image":"/img/workbench.jpg","title":"HOW A RING IS MADE","steps":["I carve the shape in wax with small files.","The wax is cast in recycled sterling silver.","I file, sand and polish it by hand. About two days."]},"closerProductId":"flow","about":[{"heading":"APPROACH","text":"I think of every ring as a small sculpture that happens to fit a finger. I studied sculpture first, and I still start with the hand, not the drawing."},{"heading":"MATERIALS","text":"Recycled sterling silver and gold vermeil. Cast down the street, finished by hand at my bench."},{"heading":"INFLUENCES","text":"River stones, Brancusi, and the way old silver goes soft at the edges."},{"heading":"WHERE I WORK","text":"A shared studio in Užupis, Vilnius. Custom pieces take two to four weeks. I ship across the EU."}]}'::jsonb, 0) on conflict (id) do nothing;
insert into public.makers (id, slug, name, studio, city, country, categories, quote, bio, portrait_url, cover_url, style, sections, status, extras, sort) values ('mara', 'mara', 'Mara', 'Studio Lehm', 'Berlin', 'LT', array['ceramics']::text[], 'I leave the edges a little uneven. That is where the character lives.', 'I build cups, bowls and vases by hand in a small studio in Neukölln. Nothing is thrown on the wheel. Every rim is pinched, so no two pieces match.', '/img/mara.jpg', '/img/ceramics-set.jpg', 'light', array['featured', 'pieces', 'journal', 'about']::text[], 'approved', '{"craft":"Hand-built ceramics","material":"Speckled stoneware","replyTime":"a few hours","acceptsCustom":true,"work":["/img/ceramics-set.jpg","/img/ripple-bowl.jpg","/img/morning-cup.jpg"],"meet":{"image":"/img/mara.jpg","qa":[["What do you make?","Cups, bowls and vases for everyday use. Built by hand, glazed in small batches."],["Why by hand?","Pinching the clay leaves soft, uneven edges. That is where the character lives."],["Do you take commissions?","Yes. Sets for a table, or a cup in a colour you love."]]},"process":{"image":"/img/ripple-bowl-wide.jpg","title":"HOW A BOWL IS MADE","steps":["I pinch and coil the clay, no wheel.","It dries slowly for a week, then the first firing.","I glaze by dipping and fire it a second time."]},"closerProductId":"twist","about":[{"heading":"APPROACH","text":"I build by hand because I like slow shapes. Every bowl starts as a ball of clay pinched between my thumbs."},{"heading":"MATERIALS","text":"Speckled stoneware and terracotta, food-safe glazes, fired twice."},{"heading":"INFLUENCES","text":"Japanese tea bowls, Berlin breakfasts, and the colour of oat milk."},{"heading":"WHERE I WORK","text":"A ground-floor studio in Neukölln, Berlin. I ship across the EU in recycled packaging."}]}'::jsonb, 1) on conflict (id) do nothing;
insert into public.makers (id, slug, name, studio, city, country, categories, quote, bio, portrait_url, cover_url, style, sections, status, extras, sort) values ('ula', 'ula', 'Ula', 'Mokume', 'Hamburg', 'LT', array['clothing', 'textiles']::text[], 'A piece of home, made to come with you.', 'I crochet hoods and scarves from wool bought at small farms in northern Germany. Every square is made by hand, one flower at a time.', '/img/crochet-duo.jpg', '/img/crochet-duo.jpg', 'light', array['featured', 'pieces', 'journal', 'about']::text[], 'approved', '{"craft":"Crochet hoods","material":"Wool from small farms","replyTime":"about a day","acceptsCustom":true,"work":["/img/crochet-duo.jpg","/img/flower-hood.jpg","/img/crochet-details.jpg"],"meet":{"image":"/img/crochet-duo.jpg","qa":[["What do you make?","Hoods and scarves made of crochet squares, mostly in moss, cream and rust."],["Why by hand?","Each square takes about forty minutes. You can feel every one of them."],["Do you take commissions?","Yes, in your colours or your size."]]},"process":{"image":"/img/crochet-detail.jpg","title":"SQUARE BY SQUARE","steps":["I crochet each flower square by hand, about forty minutes each.","Eight squares are joined into a hood.","I wash and block it so it keeps its shape."]},"closerProductId":"hood","about":[{"heading":"APPROACH","text":"Warm first, pretty second. I want pieces you actually wear every cold morning."},{"heading":"MATERIALS","text":"Wool from small farms in northern Germany, cotton for the lighter scarves."},{"heading":"INFLUENCES","text":"My grandmother’s blankets and Hamburg rain."},{"heading":"WHERE I WORK","text":"At my kitchen table in Hamburg-Altona. Made-to-order pieces take one to two weeks."}]}'::jsonb, 2) on conflict (id) do nothing;
